/// <summary>
/// VM - CB754 - Excise Register
/// </summary>
[ExtensionOf(tablestr(InventTransferLine))]
final class METInventTransferTransferLine_Extension
{
}

Method.Source:
    /// <summary>
    /// VM - CB754 - Excise Register
    /// Update the underbond field on deletion of record
    /// </summary>
    public void delete()
    {
        InventTransferTable inventTransferTable;
        METInventTransferTableExt metInventTransferTable;

        next delete();

        select firstonly UnderBond from metInventTransferTable
            exists join RecId from inventTransferTable
                where inventTransferTable.TransferId == this.TransferId 
                    && metInventTransferTable.InventTransferTable == inventTransferTable.RecId;

        if (metInventTransferTable.UnderBond)
        {
            METInventTable metInventTable;
            metTariffItemCodeBase metTariffItemCodeBase;
            InventTransferLine inventTransferLineLoc;

            select firstonly inventTransferLineLoc
                where inventTransferLineLoc.TransferId == this.TransferId
                    && inventTransferLineLoc.LineNum != this.LineNum
                exists join METTariffItemCodeBaseRecid from metInventTable
                    where metInventTable.ItemId == inventTransferLineLoc.ItemId
                        exists join metTariffItemCodeBase
                            where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid;

            if (!inventTransferLineLoc)
            {
                ttsbegin;
                metInventTransferTable.selectForUpdate(true);
                metInventTransferTable.UnderBond = NoYes::No;
                metInventTransferTable.update();
                ttscommit;
            }
        }
    }
